  const smoothstep = (a, b, v) => { const t = clamp((v - a) / (b - a)); return t * t * (3 - 2 * t); };
  let seed = 3; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647, R = (a, b) => a + rnd() * (b - a);

  /* ---------- the ground strip: the route laid out left to right, in a 900-tall space ---------- */
  const HZ = 700, L = 9000;                              // horizon; ground units under the plane = progress * L
  const LEGS = [[0, "es"], [.08, "gt"], [.3, "gulf"], [.58, "fl"], [.68, "east"], [.93, "bos"]];
