    // Florida: beach, palms, lagoons
    s += `<path d="M${X(.3) - 220} ${HZ + 34} Q${X(.3) - 60} ${HZ + 34} ${X(.3) + 10} ${HZ + 34}" stroke="#E8D6A8" stroke-width="10" fill="none" stroke-linecap="round"/>`;
    s += `<path d="M${X(.58) - 160} ${HZ + 30} Q${X(.58)} ${HZ + 34} ${X(.58) + 160} ${HZ + 30}" stroke="#E8D6A8" stroke-width="10" fill="none"/><rect x="${X(.58)}" y="${HZ + 34}" width="${X(.68) - X(.58)}" height="14" fill="#E8D6A8"/>`;
